INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Primärdaten immer direkt vom Ersteller erhoben?', 2, '[{"text": "Ja", "correct": true, "because": "Primärdaten stammen aus erster Hand"}, {"text": "Nein", "correct": false, "because": "Sekundärdaten sind anders"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel der Erhebung von Primärdaten?', 3, '[{"text": "Originale Erkenntnisse gewinnen", "correct": true, "because": "Direkte Daten sind unverfälscht"}, {"text": "Daten aggregieren", "correct": false, "because": "Sekundärdaten-Funktion"}, {"text": "Manuelle Analyse", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden erheben Primärdaten?', 5, '[{"text": "Umfragen", "correct": true, "because": "Direkte Befragung"}, {"text": "Beobachtungen", "correct": true, "because": "Eigene Datenerfassung"}, {"text": "Literaturrecherche", "correct": false, "because": "Sekundärdaten"}, {"text": "Datenaggregation", "correct": false, "because": "Verarbeitung, nicht Erhebung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Primärdaten sind unverfälscht. b) Sie sind immer öffentlich verfügbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft vertraulich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erhebung von Primärdaten?', 4, '[{"text": "Datenqualität", "correct": false, "because": "Sichert Verlässlichkeit"}, {"text": "Datenschutz", "correct": false, "because": "Schützt Personen"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Erhebung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Primärdaten immer teuer sind?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten abhängig von Methode"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig teuer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist typisch für Primärdaten?', 3, '[{"text": "Interviews", "correct": true, "because": "Direkte Datenerfassung"}, {"text": "Datenbankabfragen", "correct": false, "because": "Sekundärdaten"}, {"text": "Manuelle Aggregation", "correct": false, "because": "Nachbearbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Primärdaten?', 5, '[{"text": "Hohe Genauigkeit", "correct": true, "because": "Direkt erhoben"}, {"text": "Spezifische Relevanz", "correct": true, "because": "Auf Problem zugeschnitten"}, {"text": "Öffentliche Verfügbarkeit", "correct": false, "because": "Oft vertraulich"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Erhebung zeitaufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Primärdaten sind objektiv. b) Sie sind immer billig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft kostenintensiv"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Primärdaten?', 4, '[{"text": "Erhebungsmethode", "correct": false, "because": "Definiert Datensammlung"}, {"text": "Zieldefinition", "correct": false, "because": "Fokussiert Erhebung"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Primärdaten dasselbe wie Sekundärdaten?', 2, '[{"text": "Nein", "correct": true, "because": "Primärdaten direkt, Sekundärdaten verarbeitet"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Quellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei Primärdaten?', 4, '[{"text": "Hoher Zeitaufwand", "correct": true, "because": "Direkte Erhebung langwierig"}, {"text": "Kosten", "correct": true, "because": "Umfragen teuer"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Erhebungsproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Primärdaten immer öffentlich sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Oft vertraulich oder firmenintern"}, {"text": "Ja", "correct": false, "because": "Datenschutz relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Erhebung von Primärdaten?', 3, '[{"text": "Methodenwahl", "correct": true, "because": "Sichert Relevanz"}, {"text": "Minimale Datengenauigkeit", "correct": false, "because": "Genauigkeit entscheidend"}, {"text": "Manuelle Verarbeitung", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Primärdaten sind maßgeschneidert. b) Sie sind immer aggregiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Sekundärdatenmerkmal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge helfen bei der Erhebung von Primärdaten?', 5, '[{"text": "Online-Umfragen", "correct": true, "because": "Direkte Datensammlung"}, {"text": "Sensoren", "correct": true, "because": "Erfassen Messwerte"}, {"text": "Texteditoren", "correct": false, "because": "Kein Erhebungstool"}, {"text": "Bildbearbeitung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Primärdaten unwichtig?', 3, '[{"text": "Datenquellen", "correct": false, "because": "Bestimmen Authentizität"}, {"text": "Erhebungskontext", "correct": false, "because": "Gibt Relevanz"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Datenerhebungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Primärdaten immer manuell erhoben werden?', 2, '[{"text": "Nein", "correct": true, "because": "Automatisierte Sensoren möglich"}, {"text": "Ja", "correct": false, "because": "Automatisierung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Primärdaten für Forschung notwendig?', 3, '[{"text": "Ja", "correct": true, "because": "Liefern originale Erkenntnisse"}, {"text": "Nein", "correct": false, "because": "Oft zentral für Studien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu Primärdaten?', 4, '[{"text": "Kundenumfrage für ein Produkt", "correct": true, "because": "Direkte Datenerhebung"}, {"text": "Analyse von Marktberichten", "correct": false, "because": "Sekundärdaten"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Datenkontext"}]');
